def comps(g, diag=False):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    ds=[(-1,0),(1,0),(0,-1),(0,1)]
    if diag: ds += [(-1,-1),(-1,1),(1,-1),(1,1)]
    for r in range(H):
      for c in range(W):
       if g[r][c]==0 and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
         x,y=st.pop(); comp.append((x,y))
         for dx,dy in ds:
          p=(x+dx,y+dy)
          if 0<=p[0]<H and 0<=p[1]<W and g[p[0]][p[1]]==0 and p not in seen:
           seen.add(p); st.append(p)
        out.append(comp)
    return out
